operations.search:
overchargeHeatFormula(
  overchargeCount = 0
) {
  if (
    overchargeCount <= 0
  ) {
    return "1";
  }


  if (
    overchargeCount === 1
  ) {
    return "1d3";
  }


  if (
    overchargeCount === 2
  ) {
    return "1d6";
  }


  return "1d6+4";
}


useOvercharge({
  previousOvercharges = 0
} = {}) {
  this.assertTurnActive();


  if (
    this.restrictions?.brace
  ) {
    throw new Error(
      "Brace prevents Overcharge until the end of this turn."
    );
  }


  if (
    this.overcharge.used
  ) {
    throw new Error(
      "This unit has already Overcharged this turn."
    );
  }


  this.overcharge.used =
    true;


  this.overcharge
    .quickActionRemaining =
    1;


  this.overcharge.heatFormula =
    this.overchargeHeatFormula(
      previousOvercharges
    );


  this.closeProtocolWindow();


  this.recordHistory(
    "overcharge",
    {
      heatFormula:
        this.overcharge
          .heatFormula,

      previousOvercharges
    }
  );


  return (
    this.overcharge
      .heatFormula
  );
}

operations.replace:
useOvercharge({
  heatFormula = null
} = {}) {
  this.assertTurnActive();


  if (
    this.restrictions?.brace
  ) {
    throw new Error(
      "Brace prevents Overcharge until the end of this turn."
    );
  }


  if (
    this.overcharge.used
  ) {
    throw new Error(
      "This unit has already Overcharged this turn."
    );
  }


  this.overcharge.used =
    true;


  this.overcharge
    .quickActionRemaining =
    1;


  this.overcharge.heatFormula =
    heatFormula === null ||
    heatFormula === undefined ||
    heatFormula === ""
      ? null
      : String(
          heatFormula
        );


  this.closeProtocolWindow();


  this.recordHistory(
    "overcharge",
    {
      heatFormula:
        this.overcharge
          .heatFormula,

      progressionAuthority:
        "native-lancer"
    }
  );


  return (
    this.overcharge
      .heatFormula
  );
}
